INSERT INTO `services` (`id`, `name`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Desenvolvimento de Sistemas Sob Demanda', 'Soluções personalizadas de software para otimizar processos, automatizar tarefas e escalar seu negócio. Desenvolvemos sistemas completos sob medida, desde CRM e ERP até plataformas de gestão integrada, garantindo segurança, performance e usabilidade.', 1, NULL, NULL),
(2, 'Desenvolvimento de Aplicativos Mobile e Web', 'Criação de aplicativos intuitivos e high-performance para Android, iOS e Web. Do conceito à publicação, entregamos apps que engajam usuários, resolvem problemas e geram receita, com tecnologias modernas como Flutter, React Native ou nativas.', 1, NULL, NULL),
(3, 'Criação de Landing Pages de Alta Conversão', 'Páginas estrategicamente projetadas para transformar visitantes em clientes. Combinamos design persuasivo, copywriting irresistível e técnicas de SEO para maximizar conversões em campanhas de tráfego pago ou orgânico.', 1, NULL, NULL),
(4, 'Gestão de Tráfego Pago com ROI Ajustado', 'Campanhas inteligentes no Meta Ads, Google Ads, TikTok e LinkedIn, focadas em custo por lead (CPL) e retorno sobre investimento (ROI). Testamos audiences, criativos e mensagens para escalar suas vendas com orçamento otimizado.', 1, NULL, NULL),
(5, 'Consultoria Completa em Marketing & Tecnologia', 'Análise estratégica do seu negócio com plano de ação para alavancar vendas e eficiência operacional. Cobrimos desde funil de vendas até arquitetura de sistemas, indicando as melhores ferramentas e métricas para seu crescimento.', 1, NULL, NULL);
